<script setup lang="ts">
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('DashboardPanel')

import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api} from './session'
import {displayCurrency as currency} from './currency'
const props=defineProps<{store:string}>(),emit=defineEmits<{navigate:[value:string]}>()
const data=ref<any>(null),busy=ref(false),error=ref(''),trend=ref('7'),market=ref(''),hover=ref<number|null>(null)
const periods=[['today','今日'],['yesterday','昨日'],['7','近7日'],['30','近30日']]
const trends=[['7','7天'],['14','14天'],['30','30天'],['6m','半年'],['1y','一年']]
const series=[{key:'units',label:'销量',color:'#269ff2'},{key:'ad_spend',label:'广告花费',color:'#ff7895'},{key:'acos',label:'ACOS',color:'#91d86b'}]
const fmt=(n:any)=>n==null?'—':Number(n).toLocaleString('zh-CN',{maximumFractionDigits:2})
const money=(a:any,c:string)=>a==null?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:c}).format(Number(a))
let seq=0,timer:ReturnType<typeof setTimeout>|undefined
async function syncStock(){try{await api('/dashboard/inventory/refresh',{store:props.store});ElMessage.success('全店库存已加入后台同步');await load()}catch(e){ElMessage.error((e as Error).message)}}
async function load(){const id=++seq;busy.value=true;hover.value=null;localStorage.setItem('erp-home-currency',currency.value);try{const p=new URLSearchParams({store:props.store,marketplace:market.value,trend:trend.value,currency:currency.value});const d=await api('/dashboard?'+p);if(id===seq){data.value=d;error.value='';if(timer)clearTimeout(timer);if(['queued','running'].includes(d.inventory.sync_status))timer=setTimeout(load,8000)}}catch(e){if(id===seq)error.value=(e as Error).message}finally{if(id===seq)busy.value=false}}
const points=computed<any[]>(()=>data.value?.trend.points||[])
const maxima=computed<Record<string,number>>(()=>Object.fromEntries(series.map(s=>[s.key,Math.max(s.key==='acos'?100:1,...points.value.map(p=>Number(p[s.key]||0)))])))
const x=(i:number)=>60+i*850/Math.max(1,points.value.length-1)
const y=(p:any,k:string)=>210-Number(p[k])/maxima.value[k]!*180
function line(key:string){let path='',active=false;points.value.forEach((p,i)=>{if(p[key]==null){active=false;return}path+=`${active?'L':'M'}${x(i)},${y(p,key)} `;active=true});return path}
const labels=computed(()=>points.value.map((p,i)=>({label:data.value.trend.monthly?p.label:p.label.slice(5),i})).filter((_,i)=>i%Math.max(1,Math.ceil(points.value.length/9))===0||i===points.value.length-1))
const active=computed(()=>hover.value==null?null:points.value[hover.value])
const tooltipTitle=computed(()=>{if(!active.value)return '';const label=active.value.label;if(data.value.trend.monthly)return label+' 月汇总';return label+'（'+['周日','周一','周二','周三','周四','周五','周六'][new Date(label+'T12:00:00').getDay()]+'）'})
function pointer(e:PointerEvent){const rect=(e.currentTarget as SVGElement).getBoundingClientRect();const px=(e.clientX-rect.left)/rect.width*1000;hover.value=Math.max(0,Math.min(points.value.length-1,Math.round((px-60)/850*Math.max(1,points.value.length-1))))}
function keydown(e:KeyboardEvent){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();hover.value=Math.max(0,Math.min(points.value.length-1,(hover.value??0)+(e.key==='ArrowRight'?1:-1)))}}
const percent=(v:any)=>v==null?'—':(Number(v)>0?'+':'')+fmt(v)+'%'
const pie=computed(()=>{const t=data.value?.inventory.totals;if(!t||t.total==null||!t.total)return '#edf1ef';return `conic-gradient(#248674 0 ${t.in_stock/t.total*100}%, #87b9f5 0 100%)`})
onMounted(load);onUnmounted(()=>{seq++;if(timer)clearTimeout(timer)});watch(()=>props.store,load)
</script>
<template><div v-loading="busy"><div class="dashboard-toolbar"><span>{{store}} · 经营概览</span><div><el-select v-model="market" placeholder="全部站点" clearable style="width:145px" @change="load"><el-option v-for="(name,m) in {UK:'英国',DE:'德国',FR:'法国',ES:'西班牙',IT:'意大利',BE:'比利时',NL:'荷兰',PL:'波兰',SE:'瑞典',IE:'爱尔兰',AE:'阿联酋',SA:'沙特'}" :key="m" :label="name" :value="m"/></el-select><el-select v-model="currency" aria-label="展示币种" style="width:150px" @change="load"><el-option label="英镑 GBP" value="GBP"/><el-option label="欧元 EUR" value="EUR"/><el-option label="人民币 CNY" value="CNY"/></el-select><el-button @click="load">刷新概览</el-button></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/>
<template v-if="data"><div class="dashboard-sales"><article v-for="[key,title] in periods" :key="key" class="stat-card overview-card"><div class="overview-title"><h2>{{title}}</h2><el-tag v-if="!data.cards[key].complete" type="info" size="small">已入库部分</el-tag></div><div class="sales-primary"><div><span>销量</span><strong>{{fmt(data.cards[key].units)}}<small>件</small></strong></div><div><span>销售额</span><strong>{{money(data.cards[key].converted.amount,data.fx.currency)}}</strong></div></div>
<template v-if="key!=='today'"><div class="profit-metrics"><div><span>结算利润</span><b>{{money(data.cards[key].settlement.amount,data.fx.currency)}}</b></div><div><span>结算毛利</span><b>{{percent(data.cards[key].settlement.margin)}}{{data.cards[key].settlement.margin_partial&&data.cards[key].settlement.margin!==null?'*':''}}</b></div><div><span>订单利润</span><b>{{money(data.cards[key].order_profit.amount,data.fx.currency)}}{{data.cards[key].profit_partial?'*':''}}</b></div><div><span>订单毛利</span><b>{{percent(data.cards[key].order_margin)}}{{data.cards[key].profit_partial?'*':''}}</b></div></div><p class="metrics-note card-note">结算按入账日期的已释放金额；订单按下单日期的预估毛利。近7日、近30日不含今天。<span v-if="data.cards[key].settlement.unknown_sales_orders"> 结算中 {{data.cards[key].settlement.unknown_sales_orders}} 笔销售额待补齐，结算毛利仅按金额和销售额均已知的部分计算。</span><span v-if="data.cards[key].unknown_profit_orders"> 已估算 {{data.cards[key].known_profit_orders}} 笔，{{data.cards[key].unknown_profit_orders}} 笔待补齐；* 为已估算部分，订单毛利按同批已估算订单销售额计算。</span></p></template><div class="stat-foot">{{data.cards[key].orders}} 笔订单<span v-if="data.cards[key].estimated_amount_orders"> · {{data.cards[key].estimated_amount_orders}} 笔售价预估</span><span v-if="data.cards[key].unknown_amount_orders"> · {{data.cards[key].unknown_amount_orders}} 笔金额待返回</span><span v-if="data.cards[key].converted.missing_currencies.length"> · 汇率待补齐</span></div></article></div><p v-if="data.history_cache" class="metrics-note">历史统计：{{data.history_cache.updated_at?new Date(data.history_cache.updated_at).toLocaleString('zh-CN'):'计算中'}}<span v-if="data.history_cache.stale"> · 待本日同步完成后刷新，当前显示上一份缓存</span><span v-if="data.history_cache.error"> · {{data.history_cache.error}}</span></p><p class="metrics-note">{{data.note}} 最近订单读取：{{data.as_of?new Date(data.as_of).toLocaleString('zh-CN'):'尚未同步'}}</p>
<section class="panel ads-overview"><div class="panel-head"><h2>广告概览</h2><el-tag type="info">等待广告 API 接入</el-tag></div><div class="ads-grid"><div v-for="[,title] in periods" :key="title"><span>{{title}}广告花费</span><strong>—</strong><small>ACOS —</small></div></div></section><p class="fx-note">展示币种：{{data.fx.currency}} · 汇率来源：{{data.fx.source}} · 参考日期：{{data.fx.date||'待同步'}} / AED {{data.fx.aed_date||'待同步'}}<span v-if="data.fx.error"> · {{data.fx.error}}</span><span v-else-if="data.fx.stale"> · 汇率缓存待刷新</span><span v-else> · 按最新已发布参考汇率换算</span></p>
<section class="panel trend-panel"><div class="panel-head"><h2>业绩走势</h2><el-radio-group v-model="trend" size="small" @change="load"><el-radio-button v-for="[v,t] in trends" :key="v" :value="v">{{t}}</el-radio-button></el-radio-group></div><div class="chart-legend"><span v-for="s in series" :key="s.key"><i :style="{background:s.color}"/>{{s.label}}<small v-if="s.key!=='units'">（待接入）</small></span><span class="muted">{{data.trend.monthly?'按月汇总':'按日汇总'}} · {{data.trend.start}} — {{data.trend.end}}</span><span v-if="!data.trend.complete" class="muted">含尚未同步的时段，显示已入库数据</span></div>
<div class="trend-interactive"><svg viewBox="0 0 1000 260" role="img" aria-label="业绩走势：销量、广告花费、ACOS；左右方向键切换日期" tabindex="0" class="sales-chart" @pointermove="pointer" @pointerleave="hover=null" @focus="hover=points.length-1" @blur="hover=null" @keydown="keydown"><text x="60" y="16" class="chart-label">销量（件）</text><text x="910" y="16" text-anchor="end" class="chart-label">广告花费（{{data.fx.currency}}） / ACOS（%）</text><g v-for="n in 5" :key="n"><line x1="60" x2="910" :y1="210-(n-1)*45" :y2="210-(n-1)*45" stroke="#e7eeeb" stroke-dasharray="3 5"/><text x="49" :y="214-(n-1)*45" text-anchor="end" class="chart-label">{{fmt(maxima.units!*(n-1)/4)}}</text></g><path v-for="s in series" :key="s.key" :d="line(s.key)" :stroke="s.color" fill="none" stroke-width="2.5"/><template v-if="active&&hover!==null"><line :x1="x(hover)" :x2="x(hover)" y1="30" y2="210" stroke="#b9c4d0" stroke-dasharray="4 4"/><template v-for="s in series" :key="s.key"><circle v-if="active[s.key]!=null" :cx="x(hover)" :cy="y(active,s.key)" r="5" :fill="s.color" stroke="white" stroke-width="2"/></template></template><text v-for="l in labels" :key="l.i" :x="x(l.i)" y="244" text-anchor="middle" class="chart-label">{{l.label}}</text></svg>
<div v-if="active&&hover!==null" role="status" class="trend-tooltip" :style="{left:Math.min(72,Math.max(2,x(hover)/10-12))+'%'}"><strong>{{tooltipTitle}}</strong><div v-for="s in series" :key="s.key"><span><i :style="{background:s.color}"/>{{s.label}}</span><b>{{active[s.key]==null?'待接入':s.key==='ad_spend'?money(active[s.key],data.fx.currency):fmt(active[s.key])+(s.key==='acos'?'%':'')}}</b></div></div></div><p class="metrics-note">悬停或使用左右方向键查看当日／当月数据。广告花费与 ACOS 接入广告接口后展示；当前空值不计为零。</p></section>
<div class="home-pair stock-and-best"><div class="home-left-stack"><section class="panel inventory-overview"><div class="panel-head"><h2>库存概览</h2><TableReset table-key="DashboardPanel/table-1"/></div><el-alert v-if="data.inventory.sync_error" :title="data.inventory.sync_error" type="warning" :closable="false"/><div class="stock-layout"><div class="stock-ring" :style="{background:pie}"><div><strong>{{fmt(data.inventory.totals.total)}}</strong><small>总库存</small></div></div><div class="stock-headlines"><div><span><i class="stock-dot onhand"/>在库</span><strong>{{fmt(data.inventory.totals.in_stock)}}</strong></div><div><span><i class="stock-dot transit"/>在途</span><strong>{{fmt(data.inventory.totals.shipped)}}</strong></div></div><template v-if="true"><el-table border data-width-key="DashboardPanel/table-1" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-1', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)" :data="data.inventory.groups"><el-table-column :column-key="'column-1'" :width="tableWidths.width('table-1', 'column-1', undefined)" label="库存区域"><template #default="{row}">{{row.region==='UK'?'英国':'欧洲大陆（去重参考）'}}</template></el-table-column><el-table-column :column-key="'column-2:' + (k)" :width="tableWidths.width('table-1', 'column-2:' + (k), undefined)" v-for="[k,label] in [['in_stock','在库'],['shipped','在途'],['total','合计']]" :key="k" :label="label"><template #default="{row}">{{fmt(row[k!])}}</template></el-table-column></el-table></template></div><p class="metrics-note">在库＝FBA可售＋接收中＋仓内处理中；在途＝已发货、尚在运输中的库存。{{data.inventory.note}}</p></section><section class="panel"><div class="panel-head"><h2>绩效与邮件通知</h2><el-tag type="info">待接入</el-tag></div><el-empty description="账户健康、绩效指标及邮件通知将在接入后展示" :image-size="65"/></section></div><section class="panel"><div class="panel-head"><h2>畅销榜</h2><span class="muted">近30日 · 已入库件数</span><TableReset table-key="DashboardPanel/table-2"/></div><template v-if="true"><el-table border data-width-key="DashboardPanel/table-2" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-2', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-2', column, event)" :data="data.top" size="small"><el-table-column :column-key="'column-1'" type="index" label="#" :width="tableWidths.width('table-2', 'column-1', '42')"/><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-2', 'column-2', undefined)" label="商品" min-width="260"><template #default="{row}"><div class="bestseller-product"><el-image v-if="row.image_url" :src="row.image_url" fit="contain" loading="lazy"><template #error><span class="bestseller-placeholder">暂无图</span></template></el-image><span v-else class="bestseller-placeholder">暂无图</span><div><b :title="row.title">{{row.sku}}</b><small>ASIN：{{row.asin||'—'}}</small></div></div></template></el-table-column><el-table-column :column-key="'units'" prop="units" label="销量" :width="tableWidths.width('table-2', 'units', '70')"/><template #empty><el-empty description="暂无订单数据" :image-size="50"/></template></el-table></template></section></div><section class="panel"><div class="panel-head"><h2>个人待办事项</h2><el-tag effect="plain">员工任务分配待建设</el-tag></div><button class="todo-line" @click="emit('navigate','listing')"><span>商品接口错误</span><b>{{data.todos.listing_errors}} →</b></button><button class="todo-line" @click="emit('navigate','listing')"><span>目录资料待补齐</span><b>{{data.todos.missing_catalog}} →</b></button><div class="todo-line"><span>失败的同步任务</span><b>{{data.todos.failed_syncs}}</b></div><p class="metrics-note">当前列出系统提醒；个人任务分配、负责人和截止日期待接入。</p></section>
<section class="panel"><div class="panel-head"><div><h2>补货建议</h2><p class="metrics-note">普通商品按海运备货；结合本地可用量、采购途中、FBA 库存及到货计划。</p></div><el-button type="primary" @click="emit('navigate','replenishment')">查看补货建议</el-button></div></section></template></div></template>

<style scoped>.profit-metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 16px}</style>
